import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            idx = core.index('-')
            pre = core[idx+1:]
            core = core[:idx]
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare_pre(a, b):
        # a, b are lists of identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        for x, y in zip(a, b):
            x_num = x.isdigit()
            y_num = y.isdigit()
            if x_num and y_num:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif x_num and not y_num:
                return -1
            elif not x_num and y_num:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def compare(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        if p1[0] != p2[0]:
            return -1 if p1[0] < p2[0] else 1
        if p1[1] != p2[1]:
            return -1 if p1[1] < p2[1] else 1
        if p1[2] != p2[2]:
            return -1 if p1[2] < p2[2] else 1
        return compare_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(compare))

